/**
 * Merges `sourceLabelId` into `targetLabelId`: every issue carrying the
 * source ends up carrying the target instead (deduping issues that already
 * had both), then the source label row is deleted. Returns the target label
 * and the number of issues that carried the source label.
 */
export async function mergeLabels(
  orgId: OrgId,
  sourceLabelId: LabelId,
  targetLabelId: LabelId,
): Promise<{ label: IssueLabel; issuesRelabelled: number }> {
  const db = getDb();

  const [sourceRow, targetRow] = await Promise.all([
    Promise.resolve(
      db
        .select()
        .from(labels)
        .where(and(orgPredicate(labels.orgId, orgId), eq(labels.id, sourceLabelId)))
        .get(),
    ),
    Promise.resolve(
      db
        .select()
        .from(labels)
        .where(and(orgPredicate(labels.orgId, orgId), eq(labels.id, targetLabelId)))
        .get(),
    ),
  ]);

  if (!sourceRow) throw new Error(`Label ${sourceLabelId} not found`);
  if (!targetRow) throw new Error(`Label ${targetLabelId} not found`);

  const sourceJoins = db
    .select()
    .from(issueLabels)
    .where(
      and(
        orgPredicate(issueLabels.orgId, orgId),
        eq(issueLabels.labelId, sourceLabelId),
      ),
    )
    .all();

  const targetIssueIds = new Set(
    db
      .select({ issueId: issueLabels.issueId })
      .from(issueLabels)
      .where(
        and(
          orgPredicate(issueLabels.orgId, orgId),
          eq(issueLabels.labelId, targetLabelId),
        ),
      )
      .all()
      .map((row) => row.issueId),
  );

  const toInsert = sourceJoins
    .filter((row) => !targetIssueIds.has(row.issueId))
    .map((row) => ({
      orgId,
      issueId: row.issueId,
      labelId: targetLabelId,
    }));

  if (toInsert.length > 0) {
    db.insert(issueLabels).values(toInsert).run();
  }

  db.delete(issueLabels)
    .where(
      and(
        orgPredicate(issueLabels.orgId, orgId),
        eq(issueLabels.labelId, sourceLabelId),
      ),
    )
    .run();

  db.delete(labels)
    .where(and(orgPredicate(labels.orgId, orgId), eq(labels.id, sourceLabelId)))
    .run();

  return { label: toLabel(targetRow), issuesRelabelled: sourceJoins.length };
}

/** Batched lookup keyed by issue id, so list views avoid an N+1. */

